// The prototype's numbers come from fixtures/vidr.tsv (synthetic). This test regenerates them and checks the arithmetic of every displayed document: lines + VAT = total, credit note = exact negative of the original, replacement amounts = original amounts, and data.js is not stale.
import test from 'node:test'; import assert from 'node:assert/strict'; import { readFileSync } from 'node:fs'; import { build } from './gen-data.mjs';
const d = build(readFileSync(new URL('../../fixtures/vidr.tsv', import.meta.url), 'utf8')); const cents = (s) => Math.round(Number(s) * 100);
for (const c of d.cards) {
  test(`card ${c.id} (${c.source}): every document adds up and the pair is consistent`, () => {
    for (const k of ['orig', 'credit', 'repl']) { const sum = c[k].lines.reduce((a, r) => a + cents(r[1]), 0); assert.equal(sum, cents(c[k].total), `${k}: lines ${sum} vs total ${c[k].total}`); assert.equal(cents(c[k].parts.excl) + cents(c[k].parts.vat), cents(c[k].parts.incl)); }
    assert.equal(cents(c.credit.total), -cents(c.orig.total)); assert.equal(cents(c.repl.total), cents(c.orig.total)); assert.equal(cents(c.balance.thisOne), cents(c.orig.total));
  });
}
test('data.js is exactly what gen-data.mjs builds from the fixture', () => { const f = readFileSync(new URL('./data.js', import.meta.url), 'utf8'); assert.equal(f, '// generated by gen-data.mjs from fixtures/vidr.tsv (synthetic). Do not edit by hand.\nwindow.PROTO_DATA=' + JSON.stringify(d, null, 1) + ';\n'); });
test('the previous prototype bug (lines 111.00 + VAT 31.00 shown as 121.00) cannot appear: no document shows lines that do not add up to its total', () => { for (const c of d.cards) for (const k of ['orig', 'credit', 'repl']) assert.equal(c[k].lines.reduce((a, r) => a + cents(r[1]), 0), cents(c[k].total)); });
